insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-19', 't-assessment', 2, 'من شروط كتابة سؤال الاختيار من متعدد الجيد:', '["تضمين قرائن تدل على الإجابة","تجانس البدائل في الطول والمحتوى ومعقولية المموهات","استخدام «كل ما سبق» في كل سؤال","جعل الإجابة الصحيحة أطول البدائل دائماً"]'::jsonb, 1, 'البدائل المتجانسة والمموهات المعقولة تمنع الوصول للإجابة بالاستبعاد الشكلي، ويصاغ الجذر واضحاً بلا قرائن.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-20', 't-assessment', 3, 'أراد معلم قياس قدرة طلابه على أداء تجربة معملية فأعطاهم اختباراً ورقياً عن خطواتها فقط. أبرز مأخذ على تقويمه:', '["ضعف الثبات","ضعف صدق الأداة لقياس الهدف المهاري","طول الاختبار","كثرة الأسئلة"]'::jsonb, 1, 'الهدف مهاري أدائي، والورقي يقيس المعرفة عن الأداء لا الأداء ذاته — خلل في الصدق؛ الأنسب اختبار عملي ببطاقة ملاحظة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-21', 't-assessment', 2, 'بطاقة يسجل فيها المعلم وجود السلوك أو عدمه (نعم/لا) أثناء ملاحظة أداء الطالب:', '["سلم التقدير العددي","قائمة الرصد (الشطب)","السجل القصصي","اختبار الورقة والقلم"]'::jsonb, 1, 'قائمة الرصد ترصد حدوث السلوك من عدمه دون تدرج، بينما سلم التقدير يبين درجة الحدوث.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-22', 't-assessment', 3, 'وزّع معلم درجات اختباره حسب جدول المواصفات: موضوع أخذ 40% من الحصص ومستوياته متنوعة. كم نسبة أسئلته المستحقة في الاختبار؟', '["10%","25%","40%","70%"]'::jsonb, 2, 'الوزن النسبي للموضوع في الاختبار يعادل وزنه التدريسي: 40% من الحصص → 40% من الأسئلة/الدرجات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-01', 't-classroom', 1, 'أفضل توقيت لوضع القواعد الصفية:', '["بعد أول مشكلة سلوكية","في بداية العام الدراسي بمشاركة الطلاب","منتصف الفصل","لا حاجة لقواعد معلنة"]'::jsonb, 1, 'وضع القواعد مبكراً وبمشاركة الطلاب يرفع التزامهم بها ويمنع المشكلات قبل وقوعها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-02', 't-classroom', 2, 'من مواصفات القواعد الصفية الفعالة:', '["كثيرة ومفصلة لتغطية كل السلوكيات","سلبية الصياغة (لا تفعل...)","قليلة وواضحة وإيجابية الصياغة ومعلنة العواقب","سرية يعرفها المعلم وحده"]'::jsonb, 2, 'القواعد الجيدة قليلة ليسهل تذكرها، إيجابية الصياغة (نصغي لبعضنا)، واضحة، وعواقبها متدرجة معروفة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-03', 't-classroom', 2, 'تحدث طالبان جانبياً حديثاً خافتاً عابراً أثناء الشرح. التصرف الأنسب أولاً:', '["إيقاف الدرس وتوبيخهما","إخراجهما من الصف","إشارة غير لفظية أو الاقتراب منهما دون قطع الشرح","استدعاء ولي الأمر"]'::jsonb, 2, 'التدرج مبدأ إدارة السلوك: السلوك البسيط يعالج بأقل تدخل ودون تعطيل تعلم البقية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-04', 't-classroom', 2, 'طالب يكرر مقاطعة الدرس بتعليقات لجذب الانتباه، وتزداد المقاطعات مع ضحك الزملاء. المعالجة الأنسب:', '["الضحك مع الطلاب على تعليقاته","تجاهل السلوك مع إعطائه أدواراً إيجابية تشبع حاجته للظهور","طرده نهائياً من الحصص","خصم درجات جماعية"]'::jsonb, 1, 'السلوك هدفه لفت الانتباه؛ فيُحجب التعزيز (الانتباه للمقاطعة) ويوجه للظهور المشروع (أدوار، مسؤوليات).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-05', 't-classroom', 2, 'أخطأ طالب خطأً سلوكياً واضحاً، فعاقب المعلم الصف كاملاً بالحرمان من النشاط. الحكم على هذا الإجراء:', '["صحيح لأنه رادع عام","خاطئ؛ لا يعاقب الجميع بذنب فرد لما يولده من ظلم وإحباط","صحيح إذا تكرر الخطأ","لا يؤثر في العلاقات الصفية"]'::jsonb, 1, 'العقاب الجماعي يظلم الملتزمين ويهدم الثقة والعلاقة التربوية، والعواقب تكون فردية متناسبة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-06', 't-classroom', 2, 'عند تعزيز السلوك الإيجابي، من المهم:', '["تأجيل التعزيز لنهاية الفصل","تعزيز فوري متنوع مع تسمية السلوك المعزز تحديداً","تعزيز المتفوقين دراسياً فقط","استخدام معزز واحد دائماً للجميع"]'::jsonb, 1, 'الفورية تربط التعزيز بالسلوك، والتنويع يحفظ فاعليته، وتسمية السلوك توضح المطلوب للجميع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-07', 't-classroom', 2, 'نظام يجمع فيه الطلاب نقاطاً أو نجوماً مقابل السلوكيات الإيجابية تستبدل لاحقاً بمكافآت:', '["الإطفاء","الاقتصاد الرمزي","العقاب السالب","التعميم"]'::jsonb, 1, 'الاقتصاد الرمزي أسلوب سلوكي: معززات رمزية فورية تستبدل بمعززات فعلية لاحقاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-08', 't-classroom', 2, 'من أهم أسباب انتشار المشكلات الصفية:', '["كثرة الأنشطة المتنوعة","وضوح التعليمات","أوقات الفراغ والملل وعدم وضوح المطلوب","التعزيز المنتظم"]'::jsonb, 2, 'الفراغ والملل والغموض بيئة خصبة للمشاغبة؛ درس منظم مشوق بتعليمات واضحة وقاية أساسية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-09', 't-classroom', 2, 'اكتشف معلم حالة تنمر متكرر من طالب على زميله. التصرف الأول الواجب:', '["نصح الضحية بالصبر وتجنب المتنمر","إيقاف التنمر فوراً وحماية الطالب ثم اتخاذ الإجراءات النظامية والإرشادية","تجاهل الموقف حتى لا يتفاقم","معاقبة الطرفين معاً"]'::jsonb, 1, 'سلامة الطالب أولاً: تدخل فوري حازم لحماية الضحية، ثم الإجراءات النظامية وإشراك الإرشاد ومتابعة الحالة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-10', 't-classroom', 2, 'لضبط الانتقالات بين الأنشطة وتقليل الوقت المهدور، الأفضل:', '["ترك الانتقالات عفوية","روتين ثابت وإشارات متفق عليها وتجهيز المواد مسبقاً","إطالة كل نشاط لأقصى مدة","إلغاء الأنشطة المتعددة"]'::jsonb, 1, 'الروتينات والإشارات (عد تنازلي، جرس) تجعل الانتقال سلساً وتعظم وقت التعلم الفعلي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-11', 't-classroom', 3, 'رفض طالب تنفيذ نشاط وتحدى المعلم بانفعال أمام الصف. التصرف الأنسب لحظتها:', '["الدخول معه في مواجهة حادة أمام الجميع","الهدوء وخفض التصعيد وتأجيل النقاش لحديث فردي بعد الحصة","تنفيذ عقوبة قاسية فورية أمام الصف","تجاهله بقية الفصل الدراسي"]'::jsonb, 1, 'المواجهة العلنية تصعّد الموقف وتحرج الطرفين؛ الهدوء يحفظ هيبة الموقف ويعالج جذر المشكلة فردياً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-12', 't-classroom', 2, 'عبارة نقد تربوية صحيحة توجه للطالب المخطئ:', '["«أنت طالب فاشل»","«سلوكك بمقاطعة زملائك غير مناسب، وأثق بقدرتك على الالتزام»","«لن تتغير أبداً»","«أنت سبب مشاكل الصف كلها»"]'::jsonb, 1, 'ينقد السلوك لا الشخص، مع رسالة ثقة تفتح باب التحسن — الوصم يرسخ السلوك السلبي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-13', 't-classroom', 2, 'أنسب تنظيم لمقاعد الصف عند تنفيذ نقاش جماعي عام يشارك فيه الجميع:', '["صفوف تقليدية متراصة","حرف U (حدوة الحصان) ليرى الجميع بعضهم","مجموعات مغلقة متباعدة","جلوس عشوائي"]'::jsonb, 1, 'ترتيب U يتيح التواصل البصري بين الجميع ويناسب النقاشات العامة، والمجموعات تناسب العمل التعاوني.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-14', 't-classroom', 2, 'المقصود بالبيئة الصفية الآمنة نفسياً:', '["خلو الصف من الأجهزة الكهربائية","بيئة يجرؤ فيها الطالب على المشاركة والخطأ دون خوف من سخرية أو تحقير","صف بلا أنشطة حركية","صف صامت تماماً طوال الحصة"]'::jsonb, 1, 'الأمان النفسي أساس المشاركة والتعلم: الخطأ فرصة تعلم، ولا مكان للسخرية أو التنمر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-01', 't-values', 1, 'أخبرك طالب بمشكلة أسرية حساسة تؤثر على تحصيله. التصرف المهني الصحيح:', '["مشاركتها مع معلمي الصف جميعاً","حفظ سريتها وإحالته للموجه الطلابي وفق الأنظمة","طرحها أمام الصف للاستفادة","إخبار زملائه ليراعوه"]'::jsonb, 1, 'سرية معلومات الطلاب واجب مهني، والإحالة للمختص وفق القنوات النظامية هي التصرف الصحيح.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-02', 't-values', 2, 'أخطأ زميلك المعلم بمعلومة علمية أمام الطلاب في نشاط مشترك. التصرف اللائق:', '["تصحيحه فوراً أمام الطلاب بحدة","التنبيه اللبق على انفراد بعد الموقف","نشر خطئه في مجموعة المعلمين","إخبار المدير مباشرة"]'::jsonb, 1, 'احترام الزملاء وحفظ مكانتهم أمام الطلاب من أخلاقيات المهنة؛ فالنصح يكون سراً وبأدب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-03', 't-values', 2, 'حضر ولي أمر غاضباً محتجاً على درجة ابنه. أفضل تصرف:', '["رفض مقابلته لانشغالك","الاستماع له باحترام ثم عرض أدلة التصحيح والإجراءات النظامية بهدوء","الرد بغضب مماثل","تعديل الدرجة فوراً لإرضائه"]'::jsonb, 1, 'الاحترام والإنصات ثم الحوار الموضوعي بالأدلة وفق الأنظمة يحفظ العلاقة المهنية مع الأسرة وعدالة التقويم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-04', 't-values', 1, 'من أبرز مظاهر عدالة المعلم:', '["تمييز أبناء معارفه","المساواة في الفرص والتعامل والتقويم بين جميع الطلاب","الاهتمام بالمتفوقين فقط","التساهل مع بعض الطلاب في الغياب"]'::jsonb, 1, 'العدل وعدم المحاباة قيمة مهنية أساسية تشمل توزيع الفرص والأسئلة والتقويم والمعاملة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-05', 't-values', 2, 'المعلم قدوة لطلابه، ويشمل ذلك:', '["سلوكه داخل الفصل فقط","سلوكه ومظهره ولغته داخل المدرسة وخارجها بما فيها وسائل التواصل","تخصصه العلمي فقط","علاقاته الشخصية خارج العمل دون سواها"]'::jsonb, 1, 'أثر القدوة لا يتجزأ؛ فسلوك المعلم العام — ومنه حساباته الاجتماعية — جزء من رسالته التربوية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-06', 't-values', 2, 'لقاءات منظمة يتشارك فيها معلمو المدرسة تحليل بيانات أداء الطلاب وتبادل الممارسات الناجحة تسمى:', '["مجالس الدرجات","مجتمعات التعلم المهنية","حصص الانتظار","الاجتماعات الإدارية الطارئة"]'::jsonb, 1, 'مجتمعات التعلم المهنية آلية نمو مهني تعاوني تركز على تحسين تعلم الطلاب بالأدلة والبيانات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-07', 't-values', 2, 'الهدف الصحيح لتبادل الزيارات الصفية بين المعلمين:', '["تصيد الأخطاء وإحراج الزميل","تبادل الخبرات والتطوير المهني المشترك","ملء تقارير الأداء فقط","مراقبة التزام الزملاء بالدوام"]'::jsonb, 1, 'الزيارات التبادلية أداة تعلم مهني: ملاحظة ممارسات ناجحة وتغذية راجعة بنّاءة بروح الزمالة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-08', 't-values', 2, '«بحث يجريه المعلم بنفسه لحل مشكلة واقعية في صفه وتحسين ممارساته» يعرف بـ:', '["البحث الأساسي النظري","البحث الإجرائي","التقرير الإداري","الدراسة الطولية"]'::jsonb, 1, 'البحث الإجرائي يبدأ من مشكلة صفية حقيقية: تشخيص، تجريب حل، قياس أثر، وتعديل الممارسة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-09', 't-values', 2, 'تحليل المعلم لدرسه بعد تنفيذه متسائلاً: ما الذي نجح؟ ولماذا؟ وما الذي سأغيره؟ يسمى:', '["التقويم الختامي للطلاب","التأمل الذاتي في الممارسة","التخطيط بعيد المدى","الملاحظة الصفية"]'::jsonb, 1, 'التأمل في الممارسة نقطة انطلاق النمو المهني: وعي المعلم بقراراته وأثرها وتحسينها المستمر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-10', 't-values', 2, 'المفهوم الصحيح للتطوير المهني للمعلم:', '["ينتهي بالحصول على المؤهل الجامعي","مسؤولية ذاتية مستمرة مدى الحياة المهنية","مقصور على الدورات الإلزامية الرسمية","مسؤولية إدارة المدرسة وحدها"]'::jsonb, 1, 'النمو المهني عملية مستمرة يقودها المعلم ذاتياً بوسائل متعددة: قراءة، بحث، مجتمعات تعلم، دورات، تأمل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-11', 't-values', 2, 'لاحظ معلم آثار إيذاء ظاهرة على طالب مع تغير سلوكي واضح. الواجب المهني:', '["تجاهل الأمر لأنه شأن أسري","الإبلاغ الفوري وفق الأنظمة المعتمدة لحماية الطفل","استجواب الطالب أمام زملائه","مواجهة ولي الأمر بالاتهام مباشرة"]'::jsonb, 1, 'حماية الطالب واجب نظامي وأخلاقي؛ يبلغ المعلم الجهات المختصة بالمدرسة وفق إجراءات حماية الطفل بسرية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-12', 't-values', 2, 'أفضل قناة لتواصل المعلم مع أولياء الأمور بشأن مستوى أبنائهم:', '["حساباته الشخصية في وسائل التواصل بلا ضوابط","القنوات الرسمية المعتمدة من المدرسة مع توثيق التواصل","الطلاب أنفسهم ينقلون الرسائل الشفهية","عدم التواصل مطلقاً"]'::jsonb, 1, 'التواصل المهني يكون عبر القنوات المعتمدة وبتوثيق مناسب، حفظاً للخصوصية والمهنية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-13', 't-values', 3, 'طلب منك ولي أمر متنفذ رفع درجات ابنه مجاملةً. التصرف المهني:', '["الاستجابة حفظاً للعلاقة","الاعتذار بلطف والتمسك بعدالة التقويم وعرض سبل الدعم المشروعة للطالب","رفع الدرجات مع تنبيه الطالب","تخفيض درجات بقية الطلاب"]'::jsonb, 1, 'الأمانة والعدل لا يقبلان المساومة؛ ويُعرض البديل المشروع: خطة تحسين ومتابعة ودعم إضافي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tv-14', 't-values', 2, 'من صور تعزيز الانتماء الوطني والقيم الوسطية في التدريس:', '["إثارة النعرات والجدل الطائفي","ربط الدروس بمنجزات الوطن وترسيخ التسامح والاعتدال ونبذ الغلو","الاكتفاء بالمناسبات الرسمية","ترك الموضوع للأسرة فقط"]'::jsonb, 1, 'غرس الاعتدال والانتماء مسؤولية مستمرة تتخلل المواقف الصفية والمناهج والأنشطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-01', 't-tech', 1, 'المعيار الأول لاختيار تطبيق تقني لاستخدامه في الدرس:', '["حداثته وشهرته","خدمته للهدف التعليمي وملاءمته للطلاب","مجانيته فقط","كثرة مؤثراته البصرية"]'::jsonb, 1, 'التقنية وسيلة لا غاية؛ العبرة بخدمة الهدف التعليمي وملاءمة المحتوى وخصائص المتعلمين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-02', 't-tech', 2, 'أراد معلم كيمياء تنفيذ تجربة خطرة يصعب إجراؤها واقعياً. الحل التقني الأنسب:', '["إلغاء التجربة نهائياً","مختبر افتراضي يحاكي التجربة بأمان","وصفها شفهياً فقط","تكليف الطلاب بها منزلياً"]'::jsonb, 1, 'المختبرات الافتراضية تحاكي التجارب الخطرة أو المكلفة بأمان مع الحفاظ على الخبرة العملية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-03', 't-tech', 2, 'درس يمزج بين لقاءات حضورية وأنشطة إلكترونية عبر منصة تعليمية يسمى تعلماً:', '["متزامناً فقط","مدمجاً","ذاتياً بحتاً","تقليدياً"]'::jsonb, 1, 'التعلم المدمج يجمع مزايا الحضوري (التفاعل المباشر) والإلكتروني (المرونة وتعدد المصادر).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-04', 't-tech', 2, 'بث المعلم درساً مباشراً عبر منصة في وقت محدد يتفاعل فيه الطلاب آنياً. هذا تعلم إلكتروني:', '["غير متزامن","متزامن","مدمج","معكوس"]'::jsonb, 1, 'المتزامن يجري في وقت واحد للجميع (بث مباشر)، وغير المتزامن يتاح الرجوع إليه في أي وقت.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-05', 't-tech', 2, 'من سلوكيات المواطنة الرقمية التي يغرسها المعلم:', '["نسخ الأبحاث من الإنترنت دون توثيق","التحقق من مصداقية المعلومات واحترام الملكية الفكرية وحماية الخصوصية","مشاركة كلمات المرور مع الأصدقاء","التنمر المستتر بحسابات وهمية"]'::jsonb, 1, 'المواطنة الرقمية: استخدام آمن قانوني أخلاقي للتقنية، ومنه التوثيق والتثبت وحفظ الخصوصية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-06', 't-tech', 2, 'وصل طالباً خبر مثير عبر وسائل التواصل وأراد نشره. المهارة التي يجب أن يدربه المعلم عليها أولاً:', '["سرعة إعادة النشر","التثبت من المصدر ومصداقية الخبر قبل التفاعل معه","جمع الإعجابات","حذف التطبيق"]'::jsonb, 1, 'التثبت من المصادر جوهر التربية الإعلامية الرقمية ويقي من ترويج الشائعات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-07', 't-tech', 2, 'طالب ذكاؤه عادي وتحصيله في القراءة متدنٍ جداً مقارنة بأقرانه مع أخطاء نوعية متكررة (قلب الحروف وحذفها) دون مشكلات حسية. الحالة الأقرب:', '["إعاقة عقلية","صعوبات تعلم (عسر قراءة)","تأخر دراسي عام بسبب الإهمال","اضطراب سلوكي"]'::jsonb, 1, 'التباين بين قدرة عقلية عادية وتحصيل متدنٍ في مهارة محددة بأخطاء نوعية سمة صعوبات التعلم النمائية الأكاديمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-08', 't-tech', 2, 'طالب كثير الحركة مندفع مشتت الانتباه (ADHD). من الممارسات الصفية الداعمة له:', '["إجلاسه آخر الصف بعيداً","حرمانه من الحركة كلياً","تقريبه من المعلم وتجزئة المهام ومنحه مهام حركية مشروعة","توبيخه المتكرر أمام زملائه"]'::jsonb, 2, 'يدعم بجلوس قريب يقلل المشتتات، ومهام قصيرة، وقنوات حركة مقبولة، وتعزيز فوري.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-09', 't-tech', 2, 'طالب موهوب ينهي المهام سريعاً ثم يشاغب لملله. المعالجة التربوية الأنسب:', '["أنشطة إثرائية ومهام تفكير عليا تناسب قدراته","زيادة الواجبات الروتينية المتكررة نفسها","تجاهله لأنه متفوق","معاقبته على المشاغبة فقط"]'::jsonb, 0, 'الموهوب يحتاج إثراء وتحدياً معرفياً؛ الملل مصدر مشاغبته، والمزيد من الروتين يفاقمها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-10', 't-tech', 3, 'الوثيقة التي تحدد أهدافاً وخدمات تعليمية فردية لطالب من ذوي الإعاقة ويشارك في إعدادها فريق متعدد التخصصات مع الأسرة:', '["جدول المواصفات","الخطة التربوية الفردية (IEP)","سجل الدرجات","خطة النشاط اللاصفي"]'::jsonb, 1, 'الخطة التربوية الفردية تبنى على تشخيص دقيق وتحدد الأهداف والخدمات المساندة وتراجع دورياً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-11', 't-tech', 2, 'الفلسفة التربوية وراء دمج ذوي الاحتياجات الخاصة في المدارس العادية:', '["تخفيض التكاليف فقط","حقهم في بيئة أقل عزلاً وأثرها الاجتماعي والنفسي الإيجابي على الجميع","عدم توفر مدارس خاصة","تخفيف أعباء الأسر"]'::jsonb, 1, 'الدمج حق تربوي يعزز التقبل والانتماء وينمي المهارات الاجتماعية لذوي الإعاقة وأقرانهم معاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tx-12', 't-tech', 2, 'في صفه طالب ضعيف سمع. من الممارسات الصحيحة للمعلم:', '["التحدث وهو مدير ظهره للسبورة","إجلاسه في مقدمة الصف ومواجهته عند الحديث بوضوح","تجاهل مشاركته توفيراً للوقت","رفع الصوت بصراخ دائم"]'::jsonb, 1, 'المقعد الأمامي ومواجهة الطالب أثناء الكلام (لقراءة الشفاه) ووضوح النطق ممارسات داعمة أساسية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kp-01', 'k-percent', 1, 'ذكر مدير مدرسة أن 15% من طلاب الصف الخامس مشاركون في النادي العلمي. إذا كان عدد طلاب الصف 140 طالباً، فكم طالباً مشاركاً في النادي؟', '["14","18","21","28"]'::jsonb, 2, 'الجزء = الكل × النسبة ÷ 100 = 140 × 15 ÷ 100 = 21 طالباً. (حيلة سريعة: 10% = 14 و 5% = 7، فيكون 15% = 14 + 7 = 21).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
